[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>LearnForge — Build & Sell Online Courses, Coaching, Memberships & More</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
    :root {
      --primary: #4F46E5;
      --primary-dark: #3730a3;
      --accent: #FF6B6B;
      --accent-green: #10B981;
      --bg: #FFFFFF;
      --bg-light: #F9FAFB;
      --text: #1a1a2e;
      --text-light: #6B7280;
      --shadow: 0 4px 24px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 40px rgba(0,0,0,0.12);
      --radius: 12px;
      --radius-lg: 20px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; color: var(--text); background: var(--bg); line-height: 1.6; }
    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; display: block; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    /* Navigation */
    nav { position: fixed; top: 0; left: 0; right: 0; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); z-index: 1000; border-bottom: 1px solid rgba(0,0,0,0.06); }
    .nav-inner { max-width: 1200px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; justify-content: space-between; height: 72px; }
    .nav-logo { font-size: 24px; font-weight: 800; color: var(--primary); }
    .nav-logo span { color: var(--accent); }
    .nav-links { display: flex; gap: 32px; align-items: center; }
    .nav-links a { font-weight: 500; font-size: 15px; color: var(--text); transition: color 0.2s; }
    .nav-links a:hover { color: var(--primary); }
    .nav-cta { background: var(--primary); color: white !important; padding: 10px 24px; border-radius: 50px; font-weight: 600; transition: all 0.2s; }
    .nav-cta:hover { background: var(--primary-dark); transform: translateY(-2px); }
    .nav-mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }

    /* Hero */
    .hero { padding: 160px 0 80px; background: linear-gradient(180deg, #F5F3FF 0%, var(--bg) 100%); }
    .hero-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .hero-content { }
    .hero-badge { display: inline-flex; align-items: center; gap: 8px; background: var(--primary); color: white; padding: 8px 16px; border-radius: 50px; font-size: 14px; font-weight: 600; margin-bottom: 24px; }
    .hero h1 { font-size: 56px; font-weight: 800; line-height: 1.1; margin-bottom: 24px; letter-spacing: -1px; }
    .hero h1 span { color: var(--primary); }
    .hero-subtitle { font-size: 20px; color: var(--text-light); margin-bottom: 32px; line-height: 1.6; }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .btn-primary { background: var(--primary); color: white; padding: 16px 32px; border-radius: 50px; font-weight: 700; font-size: 16px; transition: all 0.3s; display: inline-flex; align-items: center; gap: 8px; }
    .btn-primary:hover { background: var(--primary-dark); transform: translateY(-3px); box-shadow: 0 8px 24px rgba(79,70,229,0.4); }
    .btn-secondary { background: white; color: var(--text); padding: 16px 32px; border-radius: 50px; font-weight: 600; font-size: 16px; border: 2px solid #E5E7EB; transition: all 0.3s; }
    .btn-secondary:hover { border-color: var(--primary); color: var(--primary); }

    /* Hero Preview */
    .hero-preview { background: white; border-radius: var(--radius-lg); box-shadow: var(--shadow-lg); overflow: hidden; }
    .preview-tabs { display: flex; background: var(--bg-light); border-bottom: 1px solid #E5E7EB; }
    .preview-tab { flex: 1; padding: 16px; text-align: center; font-weight: 600; font-size: 14px; cursor: pointer; transition: all 0.2s; border-bottom: 3px solid transparent; }
    .preview-tab.active { color: var(--primary); border-bottom-color: var(--primary); background: white; }
    .preview-tab:hover:not(.active) { background: white; }
    .preview-content { padding: 32px; min-height: 400px; }
    .preview-panel { display: none; }
    .preview-panel.active { display: block; animation: fadeIn 0.4s ease; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

    /* Creator Dashboard Preview */
    .creator-dashboard { background: var(--bg-light); border-radius: var(--radius); padding: 24px; }
    .dash-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; }
    .dash-title { font-size: 18px; font-weight: 700; }
    .dash-badge { background: var(--accent-green); color: white; padding: 4px 12px; border-radius: 50px; font-size: 12px; font-weight: 600; }
    .dash-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 24px; }
    .dash-stat { background: white; padding: 20px; border-radius: var(--radius); text-align: center; }
    .dash-stat-value { font-size: 28px; font-weight: 800; color: var(--primary); }
    .dash-stat-label { font-size: 12px; color: var(--text-light); margin-top: 4px; }
    .dash-course-card { background: white; border-radius: var(--radius); padding: 20px; display: flex; gap: 16px; align-items: center; }
    .dash-course-thumb { width: 80px; height: 60px; background: linear-gradient(135deg, var(--primary), #818CF8); border-radius: 8px; }
    .dash-course-info h4 { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
    .dash-course-info p { font-size: 13px; color: var(--text-light); }

    /* Student View Preview */
    .student-dashboard { background: var(--bg-light); border-radius: var(--radius); padding: 24px; }
    .student-header { display: flex; align-items: center; gap: 16px; margin-bottom: 24px; padding-bottom: 24px; border-bottom: 1px solid #E5E7EB; }
    .student-avatar { width: 48px; height: 48px; background: linear-gradient(135deg, var(--accent), #FF8A8A); border-radius: 50%; }
    .student-info h4 { font-size: 16px; font-weight: 600; }
    .student-info p { font-size: 13px; color: var(--text-light); }
    .student-progress { margin-bottom: 24px; }
    .progress-label { display: flex; justify-content: space-between; font-size: 14px; margin-bottom: 8px; }
    .progress-bar { height: 8px; background: #E5E7EB; border-radius: 4px; overflow: hidden; }
    .progress-fill { height: 100%; background: linear-gradient(90deg, var(--primary), var(--accent)); width: 68%; border-radius: 4px; }
    .student-course { background: white; border-radius: var(--radius); padding: 16px; display: flex; gap: 16px; align-items: center; margin-bottom: 12px; }
    .course-icon { width: 48px; height: 48px; background: linear-gradient(135deg, var(--primary), #818CF8); border-radius: 10px; display: flex; align-items: center; justify-content: center; color: white; font-size: 20px; }
    .course-details h5 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
    .course-details p { font-size: 13px; color: var(--text-light); }

    /* Stats Bar */
    .stats-bar { background: var(--text); color: white; padding: 64px 0; }
    .stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 48px; text-align: center; }
    .stat-item { }
    .stat-value { font-size: 56px; font-weight: 800; background: linear-gradient(135deg, var(--accent), #FFE66D); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
    .stat-label { font-size: 16px; opacity: 0.8; margin-top: 8px; }

    /* Products */
    .products { padding: 100px 0; }
    .section-header { text-align: center; max-width: 700px; margin: 0 auto 64px; }
    .section-label { display: inline-block; background: rgba(79,70,229,0.1); color: var(--primary); padding: 8px 20px; border-radius: 50px; font-size: 14px; font-weight: 600; margin-bottom: 16px; }
    .section-title { font-size: 48px; font-weight: 800; margin-bottom: 16px; letter-spacing: -1px; }
    .section-subtitle { font-size: 18px; color: var(--text-light); }
    .products-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
    .product-card { background: white; border-radius: var(--radius-lg); padding: 32px; box-shadow: var(--shadow); transition: all 0.3s; cursor: pointer; border: 2px solid transparent; }
    .product-card:hover { transform: translateY(-8px); box-shadow: var(--shadow-lg); border-color: var(--primary); }
    .product-icon { width: 64px; height: 64px; background: linear-gradient(135deg, var(--primary), #818CF8); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; margin-bottom: 24px; font-size: 28px; }
    .product-card:nth-child(2) .product-icon { background: linear-gradient(135deg, var(--accent), #FF8A8A); }
    .product-card:nth-child(3) .product-icon { background: linear-gradient(135deg, var(--accent-green), #34D399); }
    .product-card:nth-child(4) .product-icon { background: linear-gradient(135deg, #F59E0B, #FBBF24); }
    .product-card h3 { font-size: 22px; font-weight: 700; margin-bottom: 12px; }
    .product-card p { font-size: 15px; color: var(--text-light); line-height: 1.6; }
    .product-card .card-link { display: inline-flex; align-items: center; gap: 8px; color: var(--primary); font-weight: 600; margin-top: 20px; font-size: 15px; }
    .product-card:hover .card-link { gap: 12px; }

    /* Why Choose Us */
    .why-choose { padding: 100px 0; background: var(--bg-light); }
    .why-tabs { display: flex; justify-content: center; gap: 8px; margin-bottom: 48px; flex-wrap: wrap; }
    .why-tab { padding: 14px 28px; background: white; border: 2px solid #E5E7EB; border-radius: 50px; font-weight: 600; font-size: 14px; cursor: pointer; transition: all 0.3s; }
    .why-tab.active { background: var(--primary); color: white; border-color: var(--primary); }
    .why-tab:hover:not(.active) { border-color: var(--primary); color: var(--primary); }
    .why-panels { max-width: 900px; margin: 0 auto; }
    .why-panel { display: none; }
    .why-panel.active { display: block; animation: fadeIn 0.4s ease; }
    .why-panel-content { background: white; border-radius: var(--radius-lg); padding: 48px; box-shadow: var(--shadow); }
    .why-panel h3 { font-size: 32px; font-weight: 800; margin-bottom: 24px; }
    .why-panel ul { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; list-style: none; }
    .why-panel li { display: flex; align-items: flex-start; gap: 12px; font-size: 16px; padding: 16px; background: var(--bg-light); border-radius: 10px; }
    .why-panel li::before { content: "✓"; display: flex; align-items: center; justify-content: center; width: 24px; height: 24px; background: var(--primary); color: white; border-radius: 50%; font-size: 12px; flex-shrink: 0; }

    /* Global Scale */
    .global-scale { padding: 100px 0; }
    .global-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; }
    .global-content h2 { font-size: 48px; font-weight: 800; margin-bottom: 24px; letter-spacing: -1px; }
    .global-content p { font-size: 18px; color: var(--text-light); margin-bottom: 32px; }
    .global-features { display: flex; flex-direction: column; gap: 24px; }
    .global-feature { display: flex; gap: 20px; align-items: flex-start; }
    .global-feature-icon { width: 48px; height: 48px; background: linear-gradient(135deg, var(--primary), #818CF8); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 20px; flex-shrink: 0; }
    .global-feature h4 { font-size: 18px; font-weight: 700; margin-bottom: 4px; }
    .global-feature p { font-size: 15px; color: var(--text-light); }
    .global-visual { background: linear-gradient(135deg, var(--primary), #818CF8); border-radius: var(--radius-lg); padding: 48px; color: white; text-align: center; }
    .global-visual h3 { font-size: 32px; font-weight: 800; margin-bottom: 32px; }
    .globe-placeholder { width: 200px; height: 200px; background: rgba(255,255,255,0.2); border-radius: 50%; margin: 0 auto; display: flex; align-items: center; justify-content: center; font-size: 80px; }

    /* AI Automations */
    .ai-section { padding: 100px 0; background: var(--text); color: white; }
    .ai-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .ai-content h2 { font-size: 48px; font-weight: 800; margin-bottom: 24px; }
    .ai-content p { font-size: 18px; opacity: 0.8; margin-bottom: 32px; }
    .ai-features { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
    .ai-feature { background: rgba(255,255,255,0.1); padding: 20px; border-radius: var(--radius); }
    .ai-feature h4 { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
    .ai-feature p { font-size: 14px; opacity: 0.7; }
    .ai-visual { background: linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0.05)); border-radius: var(--radius-lg); padding: 48px; text-align: center; }
    .ai-icon { font-size: 80px; margin-bottom: 24px; }
    .ai-visual p { font-size: 18px; opacity: 0.8; }

    /* Testimonials */
    .testimonials { padding: 100px 0; }
    .testimonials .section-header { margin-bottom: 48px; }
    .testimonial-carousel { position: relative; max-width: 900px; margin: 0 auto; overflow: hidden; }
    .testimonial-track { display: flex; transition: transform 0.5s ease; }
    .testimonial-card { min-width: 100%; padding: 0 16px; }
    .testimonial-inner { background: white; border-radius: var(--radius-lg); padding: 48px; box-shadow: var(--shadow); text-align: center; }
    .testimonial-quote { font-size: 20px; font-style: italic; color: var(--text); margin-bottom: 32px; line-height: 1.8; }
    .testimonial-quote::before { content: ""; }
    .testimonial-author { display: flex; align-items: center; justify-content: center; gap: 16px; }
    .testimonial-avatar { width: 56px; height: 56px; background: linear-gradient(135deg, var(--primary), var(--accent)); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-weight: 700; font-size: 20px; }
    .testimonial-info { text-align: left; }
    .testimonial-name { font-size: 18px; font-weight: 700; }
    .testimonial-role { font-size: 14px; color: var(--text-light); }
    .testimonial-tag { display: inline-block; background: rgba(79,70,229,0.1); color: var(--primary); padding: 6px 16px; border-radius: 50px; font-size: 13px; font-weight: 600; margin-top: 8px; }
    .carousel-controls { display: flex; justify-content: center; gap: 16px; margin-top: 32px; }
    .carousel-btn { width: 48px; height: 48px; border-radius: 50%; background: white; border: 2px solid #E5E7EB; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s; font-size: 18px; }
    .carousel-btn:hover { background: var(--primary); color: white; border-color: var(--primary); }
    .carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 24px; }
    .carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: #E5E7EB; cursor: pointer; transition: all 0.2s; }
    .carousel-dot.active { background: var(--primary); width: 32px; border-radius: 5px; }

    /* Pricing */
    .pricing { padding: 100px 0; background: var(--bg-light); }
    .pricing-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 64px; }
    .pricing-card { background: white; border-radius: var(--radius-lg); padding: 40px; box-shadow: var(--shadow); transition: all 0.3s; }
    .pricing-card:hover { transform: translateY(-8px); box-shadow: var(--shadow-lg); }
    .pricing-card.featured { border: 3px solid var(--primary); position: relative; }
    .pricing-card.featured::before { content: "Most Popular"; position: absolute; top: -14px; left: 50%; transform: translateX(-50%); background: var(--primary); color: white; padding: 6px 20px; border-radius: 50px; font-size: 13px; font-weight: 600; }
    .pricing-name { font-size: 24px; font-weight: 700; margin-bottom: 8px; }
    .pricing-price { font-size: 48px; font-weight: 800; color: var(--primary); margin-bottom: 8px; }
    .pricing-price span { font-size: 16px; color: var(--text-light); font-weight: 400; }
    .pricing-desc { font-size: 15px; color: var(--text-light); margin-bottom: 24px; }
    .pricing-features { list-style: none; margin-bottom: 32px; }
    .pricing-features li { display: flex; align-items: center; gap: 12px; font-size: 15px; padding: 10px 0; border-bottom: 1px solid #F3F4F6; }
    .pricing-features li::before { content: "✓"; color: var(--accent-green); font-weight: 700; }
    .pricing-cta { width: 100%; padding: 16px; border-radius: 50px; font-weight: 700; font-size: 16px; cursor: pointer; transition: all 0.3s; border: 2px solid var(--primary); background: transparent; color: var(--primary); }
    .pricing-cta:hover { background: var(--primary); color: white; }
    .pricing-card.featured .pricing-cta { background: var(--primary); color: white; }
    .pricing-card.featured .pricing-cta:hover { background: var(--primary-dark); }

    /* Integrations */
    .integrations { padding: 100px 0; }
    .integrations-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; margin-top: 64px; }
    .integration-item { background: var(--bg-light); border-radius: var(--radius); padding: 24px; text-align: center; transition: all 0.3s; }
    .integration-item:hover { background: white; box-shadow: var(--shadow); transform: translateY(-4px); }
    .integration-icon { width: 48px; height: 48px; background: white; border-radius: 10px; margin: 0 auto 12px; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 18px; box-shadow: 0 2px 8px rgba(0,0,0,0.06); }
    .integration-item span { font-size: 13px; font-weight: 500; color: var(--text-light); }

    /* FAQ */
    .faq { padding: 100px 0; background: var(--bg-light); }
    .faq-list { max-width: 800px; margin: 0 auto; }
    .faq-item { background: white; border-radius: var(--radius); margin-bottom: 12px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.04); }
    .faq-question { padding: 24px 28px; font-size: 18px; font-weight: 600; cursor: pointer; display: flex; justify-content: space-between; align-items: center; transition: all 0.2s; }
    .faq-question:hover { color: var(--primary); }
    .faq-question::after { content: "+"; font-size: 24px; transition: transform 0.3s; }
    .faq-item.active .faq-question::after { transform: rotate(45deg); }
    .faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; }
    .faq-answer-inner { padding: 0 28px 24px; font-size: 16px; color: var(--text-light); line-height: 1.7; }
    .faq-item.active .faq-answer { max-height: 200px; }

    /* CTA Banner */
    .cta-banner { padding: 100px 0; background: linear-gradient(135deg, var(--primary), var(--primary-dark)); color: white; text-align: center; }
    .cta-banner h2 { font-size: 48px; font-weight: 800; margin-bottom: 24px; }
    .cta-banner p { font-size: 20px; opacity: 0.9; margin-bottom: 40px; max-width: 600px; margin-left: auto; margin-right: auto; }
    .cta-banner .btn-primary { background: white; color: var(--primary); }
    .cta-banner .btn-primary:hover { background: #F5F3FF; transform: translateY(-3px); }

    /* Footer */
    footer { background: var(--text); color: white; padding: 80px 0 40px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 64px; margin-bottom: 64px; }
    .footer-brand { }
    .footer-logo { font-size: 28px; font-weight: 800; margin-bottom: 16px; }
    .footer-logo span { color: var(--accent); }
    .footer-brand p { color: rgba(255,255,255,0.6); font-size: 15px; line-height: 1.7; max-width: 300px; }
    .footer-col h4 { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 20px; opacity: 0.5; }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 12px; }
    .footer-col a { color: rgba(255,255,255,0.8); font-size: 15px; transition: color 0.2s; }
    .footer-col a:hover { color: white; }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 40px; display: flex; justify-content: space-between; align-items: center; font-size: 14px; color: rgba(255,255,255,0.5); }

    /* Responsive */
    @media (max-width: 1024px) {
      .hero-inner { grid-template-columns: 1fr; text-align: center; }
      .hero h1 { font-size: 44px; }
      .hero-actions { justify-content: center; }
      .products-grid { grid-template-columns: repeat(2, 1fr); }
      .global-inner, .ai-inner { grid-template-columns: 1fr; }
      .pricing-cards { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-mobile-toggle { display: block; }
      .hero { padding: 120px 0 60px; }
      .hero h1 { font-size: 36px; }
      .section-title { font-size: 36px; }
      .products-grid { grid-template-columns: 1fr; }
      .why-panel ul { grid-template-columns: 1fr; }
      .ai-features { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: 1fr; gap: 32px; }
      .integrations-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
    }

    /* Mobile Nav */
    .mobile-menu { display: none; position: fixed; top: 72px; left: 0; right: 0; background: white; padding: 24px; box-shadow: var(--shadow); z-index: 999; }
    .mobile-menu.active { display: block; }
    .mobile-menu a { display: block; padding: 16px 0; font-weight: 500; border-bottom: 1px solid #E5E7EB; }
    .mobile-menu .nav-cta { display: inline-block; margin-top: 16px; }
  </style>
</head>
<body>

  <!-- Navigation -->
  <nav>
    <div class="nav-inner">
      <a href="index.html" class="nav-logo">Learn<span>Forge</span></a>
      <div class="nav-links">
        <a href="online-courses.html">Online Courses</a>
        <a href="digital-downloads.html">Digital Downloads</a>
        <a href="memberships.html">Memberships</a>
        <a href="coaching.html">Coaching</a>
        <a href="#pricing" class="nav-cta">Start Free Trial</a>
