    function moveTestimonial(direction) {
      currentTestimonial = (currentTestimonial + direction + totalTestimonials) % totalTestimonials;
      updateTestimonialPosition();
    }
    function goToTestimonial(index) {
      currentTestimonial = index;
      updateTestimonialPosition();
