  <script>
    let currentTestimonial = 0;
    const totalTestimonials = 3;
    function moveTestimonial(direction) {
      currentTestimonial = (currentTestimonial + direction + totalTestimonials) % totalTestimonials;
      updateTestimonialPosition();
    }
    function goToTestimonial(index) {
      currentTestimonial = index;
      updateTestimonialPosition();
    }
    function updateTestimonialPosition() {
      document.getElementById('testimonial-track').style.transform = `translateX(-${currentTestimonial * 100}%)`;
      document.querySelectorAll('.carousel-dot').forEach((dot, i) => dot.classList.toggle('active', i === currentTestimonial));
    }
    function toggleFaq(element) {
      const item = element.parentElement;
      const wasActive = item.classList.contains('active');
      document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('active'));
      if (!wasActive) item.classList.add('active');
    }
  </script>
